//! Real cold/warm report replay from the same funded Original notice owner.
#[path="../../../shared/test_scratch.rs"]mod scratch;
#[path="../../../../analyze/fixtures/report_configuration.rs"]mod report_configuration;
use dmbc::{runner_host::BuildHost,request::{BuildRequest,BuildOutcome,Command},policy_request::{AnalysisContext,PolicyInputRequest,WorkspacePolicyRequest,WorkspaceAuxiliaryQuestion as Q}};
use std::{io::{self,Write},path::{Path,PathBuf}};
fn put(root:&Path,p:&str,text:&str){let p=root.join(p);std::fs::create_dir_all(p.parent().unwrap()).unwrap();std::fs::write(p,text).unwrap()}
fn fixture()->(PathBuf,BuildRequest){let root=scratch::dir("real-original-notice-report-replay");put(&root,"deepquarry.dme","#include \"code/probe.dm\"\n#warn ROOT_WARNING\n");put(&root,"code/probe.dm","#warn CHILD_WARNING\n/obj/probe\n    var/value\n/obj/probe/ui_data()\n    return list(value)\n");put(&root,"code/_generated/reads.dm","// actual stale output\n");put(&root,"tools/ci/lint_scopes.toml",&report_configuration::with_overlay(""));let Command::Build(r)=dmbc::cli::parse(&["prepare-query".into(),root.join("deepquarry.dme").to_string_lossy().into_owned()]).unwrap()else{panic!("real PrepareQuery")};let mut req=*r;req.no_cache=true;req.exact_inputs=true;req.progress_enabled=false;req.workers=1;req.timeout_seconds=Some(60);req.engine_template=None;req.bootstrap_catalog=false;req.cache_root=Some(root.join("cache"));req.policy_inputs=Some(PolicyInputRequest{analysis_context:Some(AnalysisContext::OriginalAnalyze0290),workspace:Some(WorkspacePolicyRequest{root:root.clone(),recursive_roots:vec![root.join("code")],configuration:root.join("tools/ci/lint_scopes.toml")}),workspace_auxiliary:vec![Q::DerivedReads],..Default::default()});(root,req)}
fn prepare(host:&mut BuildHost,r:&BuildRequest)->BuildOutcome{dmbc::request_runner::run_build_with_host(r.clone(),host).unwrap()}
fn rendered(host:&BuildHost,r:&BuildRequest,prepared:&BuildOutcome)->Vec<u8>{dmbc::diagnostics::begin(Default::default());let mut output=Vec::new();let mut called=false;host.with_prepared_derived_report_to(r,prepared,&mut output,|_,_|{called=true;Ok(())}).unwrap();assert!(called);let text=std::str::from_utf8(&output).unwrap();assert!(text.find("CHILD_WARNING").unwrap()<text.find("ROOT_WARNING").unwrap());let tally=dmbc::diagnostics::tally();assert_eq!(tally.warnings,2);assert_eq!(tally.errors,0);output}
fn notice_bytes(host:&BuildHost)->u64{host.query_snapshot_retention_census().owners.iter().filter(|row|row.owner.starts_with("query_snapshot.original_notices")).map(|row|row.unique_known_capacity_bytes).sum()}
#[test]fn actual_cold_and_warm_report_replay_preserve_order_tally_and_stable_actual_retention(){let(_,r)=fixture();let mut host=BuildHost::default();let prepared=prepare(&mut host,&r);let bytes=notice_bytes(&host);assert!(bytes>0,"actual notice buffers/owner must be observed, not a reservation total");let cold=rendered(&host,&r,&prepared);for _ in 0..3{assert_eq!(rendered(&host,&r,&prepared),cold);assert_eq!(notice_bytes(&host),bytes,"replay must not grow a per-report retained copy")}}
struct Failed;impl Write for Failed{fn write(&mut self,_:&[u8])->io::Result<usize>{Err(io::Error::from_raw_os_error(1450))}fn flush(&mut self)->io::Result<()>{panic!("real first write failure returned immediately")}}
#[test]fn actual_notice_writer_error_precedes_callback_and_fresh_report_recovers(){let(_,r)=fixture();let mut host=BuildHost::default();let prepared=prepare(&mut host,&r);let mut called=false;let e=host.with_prepared_derived_report_to(&r,&prepared,&mut Failed,|_,_|{called=true;Err::<(),_>(io::Error::from_raw_os_error(5))}).unwrap_err();assert_eq!(e.raw_os_error(),Some(1450));assert!(!called,"report callback cannot run after actual diagnostic sink failure");rendered(&host,&r,&prepared);}
#[test]fn actual_pressure_release_refuses_clean_replay_until_genuine_repreparation(){let(_,r)=fixture();let mut host=BuildHost::default();let prepared=prepare(&mut host,&r);rendered(&host,&r,&prepared);assert!(notice_bytes(&host)>0);host.release_optional_query_sources().unwrap();assert_eq!(notice_bytes(&host),0,"the source snapshot must release its own actual notice-plan alias; no claim is made about another retained frontend or RSS");let mut called=false;let e=host.with_prepared_derived_report_to(&r,&prepared,&mut Vec::new(),|_,_|{called=true;Ok(())}).unwrap_err();assert_eq!(e.kind(),io::ErrorKind::NotConnected);assert!(e.to_string().contains("reprepare"));assert!(!called);let current=prepare(&mut host,&r);rendered(&host,&r,&current);assert!(notice_bytes(&host)>0)}
#[test]fn wrong_role_report_never_replays_notices_or_enters_callback(){let(_,r)=fixture();let mut host=BuildHost::default();let prepared=prepare(&mut host,&r);let mut wrong=r;wrong.policy_inputs.as_mut().unwrap().workspace_auxiliary=vec![Q::SemReads];dmbc::diagnostics::begin(Default::default());let mut output=Vec::new();let mut called=false;assert!(host.with_prepared_derived_report_to(&wrong,&prepared,&mut output,|_,_|{called=true;Ok(())}).is_err());assert!(output.is_empty());assert!(!called);assert_eq!(dmbc::diagnostics::tally().warnings,0)}

#[test]fn actual_integrated_cold_report_defers_prepare_notices_then_replays_exactly_once(){let(_,r)=fixture();let mut host=BuildHost::default();dmbc::diagnostics::begin(Default::default());let mut output=Vec::new();let result=host.with_derived_attempt_report_to(r.clone(),&mut output,|_,_|Ok(())).unwrap();let prepared=result.preparation.unwrap();result.report.unwrap().unwrap();let text=String::from_utf8(output.clone()).unwrap();assert_eq!(text.matches("CHILD_WARNING").count(),1);assert_eq!(text.matches("ROOT_WARNING").count(),1);assert_eq!(dmbc::diagnostics::tally().warnings,2,"integrated cold preparation must not render a second copy before the actual report");assert_eq!(rendered(&host,&r,&prepared),output,"later independent report replays the same authentic notices once");let standalone=prepare(&mut host,&r);assert_eq!(dmbc::diagnostics::tally().warnings,2,"standalone preparation owns its separate diagnostic output");assert_eq!(rendered(&host,&r,&standalone),output,"a later standalone followup report owns one replay, not a global rendered stamp");}
